fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Compute the initial distance in a larger integer type to avoid overflow
    let initial_dist = (a as i16 - b as i16).abs();
    let moves = x as i16;
    let max_dist = (n - 1) as i16;

    // Add moves to the initial distance and cap at n - 1
    let final_dist = (initial_dist + moves).min(max_dist);

    final_dist as i8
}

